export async function eliminarMuestraRepository(muestraId) {
  await MODELO_MUESTRA.build(EntityRepository).delete(
    { muestraId }
  );
}

import { modificarCantidadMlService } from './service.mjs';

export async function handler(event) {
  const muestraId = Number(event.pathParameters.muestraId);
  const { cantidadMl } = JSON.parse(event.body);
  const resultado = await modificarCantidadMlService(muestraId, cantidadMl);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { modificarCantidadMlRepository } from './repository.mjs';

export function modificarCantidadMlService(muestraId, cantidadMl) {
  return modificarCantidadMlRepository(muestraId, cantidadMl);
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_MUESTRA, MODELO_LABORATORIO } from '../../models/laboratorio-muestra.model.mjs';

export async function modificarCantidadMlRepository(muestraId, cantidadMl) {
  const { Attributes } = await MODELO_MUESTRA.build(EntityRepository).update(
    { muestraId, cantidadMl },
    {
      condition: { attr: 'muestraId', exists: true },
      returnValues: 'ALL_NEW'
    }
  );
  return Attributes;
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_MUESTRA, MODELO_LABORATORIO } from '../../models/laboratorio-muestra.model.mjs';

export async function buscarLaboratorioRepository(laboratorioId) {
  const { Item } = await MODELO_LABORATORIO.build(EntityRepository).get(
    { laboratorioId },
    { consistent: true }
  );
  return Item ?? null;
}

export async function consultarLaboratorioRepository(laboratorioId, minimo) {
  const { Items = [] } = await MODELO_MUESTRA.build(EntityRepository).query(
    { index: 'PorLaboratorio', partition: laboratorioId },
    { filters: { Muestra: { attr: 'cantidadMl', gte: minimo } } }
  );
  return Items;
}

